pub fn transition(actor: &Device, s: &Store, cmd: &Command) -> Result<(Option<Store>, Reply), Error> {
    match cmd {
        Command::Query => Ok((None, Reply::Listing)),
        Command::AddSpool { tag, len, readable } => {
            if !actor.admin {
                return Err(Error::Forbidden);
            }
            add_spool(s, *tag, *len, *readable)
        }
        Command::EditSpool { id, tag, len, same, readable } => {
            if !actor.admin {
                return Err(Error::Forbidden);
            }
            edit_spool(s, *id, *tag, *len, *same, *readable)
        }
        Command::DeleteSpool { id } => {
            if !actor.admin {
                return Err(Error::Forbidden);
            }
            delete_spool(s, *id)
        }
    }
}

