fn replace_slot(slots: &[Slot], id: u32, ns: Slot) -> Vec<Slot> {
    let mut out: Vec<Slot> = Vec::new();
    let mut i = 0;
    while i < slots.len() {
        let s = slots[i];
        if s.id == id {
            out.push(ns);
        } else {
            out.push(s);
        }
        i += 1;
    }
    out
}

